got = json.loads(p.stdout)
def diff(a,b,path=''):
    if type(a)!=type(b): print('type',path,type(a),type(b)); return
    if isinstance(a,dict):
        if set(a)!=set(b): print('keys',path,set(a)^set(b)); return
        for k in a: diff(a[k],b[k],path+'/'+k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('len',path,len(a),len(b)); return
        for i,(x,y) in enumerate(zip(a,b)): diff(x,y,path+'/'+str(i))
    else:
        if a!=b: print('val',path,repr(a),repr(b))
